package org.example.server.returns;
import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/returns") public class ReturnController{private final ReturnService s;public ReturnController(ReturnService s){this.s=s;}@GetMapping public List<ReturnDtos.Summary> list(@RequestParam String type){return s.summaries(type);}@GetMapping("/returned") public Map<String,Double> returned(@RequestParam String type,@RequestParam String invoice){return s.returned(type,invoice);}@PostMapping public ReturnDtos.Created create(@RequestBody ReturnDtos.CreateRequest d){return s.create(d);}@GetMapping("/{no}") public ReturnDtos.Details details(@PathVariable String no){return s.details(no);}@PutMapping("/{no}") public ReturnDtos.Ok update(@PathVariable String no,@RequestBody ReturnDtos.UpdateRequest d){s.update(no,d.field(),d.value());return ok("Updated");}@PostMapping("/{no}/refund") public ReturnDtos.Ok refund(@PathVariable String no,@RequestBody ReturnDtos.RefundRequest d){s.refund(no,d.amount());return ok("Recorded");}@PostMapping("/{no}/cancel") public ReturnDtos.Ok cancel(@PathVariable String no,@RequestParam boolean sales){s.cancel(no,sales);return ok("Cancelled");}@DeleteMapping("/{no}") public ReturnDtos.Ok delete(@PathVariable String no,@RequestParam boolean sales){s.delete(no,sales);return ok("Deleted");}private ReturnDtos.Ok ok(String m){return new ReturnDtos.Ok(true,m);}}
